//Pega o csv como texto cindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text =
  typeof csvRaw === "string" ? csvRaw : JSON.stringify(csvRaw);

const lines = text
  .split(/\r?\n/)
  .map(line => line.trim())
  .filter(Boolean);

if (lines.length === 0) {
  return [{ json: { investimentos: [] } }];
}

const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};

  headers.forEach((h, i) => {
    obj[h] = cols[i] ?? "";
  });

  // Converte valores como "R$ 1.000,00" em 1000.
  const minimo = String(obj.minimo ?? "")
    .replace(/[^\d,.-]/g, "")
    .replace(/\.(?=\d{3}(?:[.,]|$))/g, "")
    .replace(",", ".");

  obj.minimo = Number(minimo);

  return obj;
});

return [{ json: { investimentos } }];

// Modo: Run Once for All Items
const dados = $input.first().json;
const clientes = dados.body?.clientes ?? dados.clientes;
const investimentos = dados.investimentos;

if (!Array.isArray(clientes) || !Array.isArray(investimentos)) {
  throw new Error('O Merge deve fornecer body.clientes e investimentos como listas.');
}

const normalizar = valor => String(valor ?? '').trim().toLowerCase();
const moeda = valor => valor.toLocaleString('pt-BR', {
  style: 'currency', currency: 'BRL',
});

function numero(valor) {
  if (typeof valor === 'number') return valor;
  let texto = String(valor ?? '').replace(/[^\d,.-]/g, '');
  if (!texto) return NaN;
  if (texto.includes(',')) {
    texto = texto.replace(/\./g, '').replace(',', '.');
  }
  return Number(texto);
}

const focos = {
  conservador: 'segurança e opções de renda fixa',
  moderado: 'equilíbrio entre risco e retorno',
  arrojado: 'maior potencial de retorno, com maior risco e oscilação',
};

return clientes.map(cliente => {
  const saldo = numero(cliente.saldo);
  if (!Number.isFinite(saldo) || saldo < 0) {
    throw new Error('Saldo inválido para o cliente: ' + cliente.nome);
  }

  const opcoes = investimentos.filter(investimento => {
    const minimo = numero(investimento.minimo);
    return normalizar(investimento.perfil) === normalizar(cliente.perfil)
      && Number.isFinite(minimo) && minimo >= 0 && minimo <= saldo;
  });

  const lista = opcoes.map(opcao =>
    opcao.produto + ' (aplicação mínima: ' + moeda(numero(opcao.minimo)) + ')'
  ).join('; ');

  const foco = focos[normalizar(cliente.perfil)] ?? 'seus objetivos';
  const mensagem = opcoes.length
    ? 'Olá, ' + cliente.nome + '! Seu perfil é ' + cliente.perfil
      + ', com foco em ' + foco + '. Considerando seu saldo de ' + moeda(saldo)
      + ', estas opções da base do projeto atendem ao perfil e ao valor mínimo: '
      + lista + '. Os valores mínimos se referem a cada opção individualmente.'
    : 'Olá, ' + cliente.nome + '! Não encontramos na base do projeto opções para o perfil '
      + cliente.perfil + ' com aplicação mínima de até ' + moeda(saldo) + '.';

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      saldo,
      investimentos: opcoes,
      mensagem,
    },
  };
});

// Entrega um cliente por item para o prompt da IA.
return $input.all().map((item, index) => ({
  json: {
    nome: item.json.nome,
    email: item.json.email,
    perfil: item.json.perfil,
    saldo: item.json.saldo,
    investimentos: item.json.investimentos,
  },
  pairedItem: { item: index },
}));

// Modo: Run Once for All Items
// Recupera o cliente vinculado à resposta da IA.
return $input.all().map((item, index) => {
  const cliente = $('Code in JavaScript2').itemMatching(index).json;

  const mensagem = (item.json.output ?? [])
    .flatMap(resposta => resposta.content ?? [])
    .filter(conteudo => conteudo.type === 'output_text')
    .map(conteudo => conteudo.text ?? '')
    .join('\n')
    .replace(/\r\n/g, '\n')
    .replace(/\*\*(.*?)\*\*/g, '$1')
    .trim();

  const emailTo = String(cliente.email ?? '').trim();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailTo)) {
    throw new Error('Email inválido para: ' + cliente.nome);
  }
  if (!mensagem) {
    throw new Error('A IA não retornou uma mensagem para: ' + cliente.nome);
  }

  return {
    json: {
      subject: 'Opções de investimento — perfil ' + cliente.perfil + ' (simulação)',
      mensagem,
      email_to: emailTo,
    },
    pairedItem: { item: index },
  };
});
